import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.CWgsre3x.js";const p=JSON.parse('{"title":"Staff and chauffeur onboarding checklist","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/staff-onboarding.md","filePath":"getting-started/staff-onboarding.md"}'),n={name:"getting-started/staff-onboarding.md"};function o(s,e,c,l,d,f){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="staff-and-chauffeur-onboarding-checklist" tabindex="-1">Staff and chauffeur onboarding checklist <a class="header-anchor" href="#staff-and-chauffeur-onboarding-checklist" aria-label="Permalink to &quot;Staff and chauffeur onboarding checklist&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Operational guidance reviewed against v0.7.26. Verify the installed release, permissions and approved scope. Training uses authorized synthetic data; this guide does not authorize commercial activation.</p></div><h2 id="before-the-first-shift" tabindex="-1">Before the first shift <a class="header-anchor" href="#before-the-first-shift" aria-label="Permalink to &quot;Before the first shift&quot;">​</a></h2><ul><li>[ ] Verify approved identity, duties, company and required access.</li><li>[ ] Request individual backend account and minimum role from the authorized administrator.</li><li>[ ] For a chauffeur, create or review the driver record, approved vehicle/roster and account association.</li><li>[ ] Deliver credentials through a secure channel; require strong unique passwords.</li><li>[ ] Test actual role sign-in, company scope, logout and denied actions using synthetic records.</li><li>[ ] Test mobile browser, connectivity, assignment visibility, independent outbound/return progress and arrival brief where available.</li><li>[ ] Explain passenger privacy, cash collection and physical handover procedures.</li><li>[ ] Test explicit on-duty GPS opt-in only where approved; physical mobile GPS acceptance remains separate.</li><li>[ ] Provide shift escalation and support contacts; record training acceptance.</li></ul><p>The checklist is a manual operational aid, not an account creation form or automatically saved approval. Public job applications are not account provisioning. On departure, request backend revocation of access and active sessions, verify denial, and preserve operational records.</p><p>See <a href="/plus/staff-administration.html">Staff administration</a>, <a href="/plus/chauffeur-workspace.html">Chauffeur workspace</a> and <a href="/security-privacy/">Security &amp; Privacy</a>.</p>',6)])])}const h=a(n,[["render",o]]);export{p as __pageData,h as default};
